(function(){
  'use strict';
  const D=window.ROS2Hub,L=window.HubLogic,$=id=>document.getElementById(id);
  if(!D){$('main').textContent='课程数据未加载。请确认 content.js 与 index.html 位于同一目录。';return;}
  const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const inline=x=>esc(x).replace(/`([^`]+)`/g,'<code>$1</code>').replace(/\*\*([^*]+)\*\*/g,'<strong>$1</strong>');
  const iconPaths={search:'M21 21l-5-5M18 10a8 8 0 1 1-16 0 8 8 0 0 1 16 0',home:'M3 11l9-8 9 8M5 10v11h5v-7h4v7h5V10',book:'M3 3h7l2 2 2-2h7v17h-7l-2 2-2-2H3zM12 5v17',code:'M8 5l-6 7 6 7M16 5l6 7-6 7M14 3l-4 18',grid:'M3 3h7v7H3zM14 3h7v7h-7zM3 14h7v7H3zM14 14h7v7h-7z',compass:'M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0M16 8l-3 5-5 3 3-5z',layers:'M2 7l10-5 10 5-10 5zM2 12l10 5 10-5M2 17l10 5 10-5',tool:'M14 6l4 4 4-4a7 7 0 0 1-9 9l-7 7-4-4 7-7a7 7 0 0 1 9-9z',external:'M14 3h7v7M21 3L10 14M10 3H3v18h18v-7',arrow:'M4 12h16M14 6l6 6-6 6',menu:'M3 5h18M3 12h18M3 19h18',sun:'M12 3V1M12 23v-2M3 12H1M23 12h-2M5 5L3 3M21 21l-2-2M5 19l-2 2M21 3l-2 2M17 12a5 5 0 1 1-10 0 5 5 0 0 1 10 0',bookmark:'M5 3h14v19l-7-5-7 5z',download:'M12 3v12M7 10l5 5 5-5M3 16v5h18v-5',check:'M4 12l5 5L21 5',cpu:'M6 6h12v12H6zM9 1v5M15 1v5M9 18v5M15 18v5M1 9h5M1 15h5M18 9h5M18 15h5',info:'M12 11v6M12 7v1M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0'};
  const I=name=>`<svg class="icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${iconPaths[name]||iconPaths.book}"/></svg>`;
  function icons(){document.querySelectorAll('[data-icon]').forEach(el=>{el.innerHTML=I(el.dataset.icon);});}
  const ids=D.lessons.map(x=>x.id),lessonMap=new Map(D.lessons.map(x=>[x.id,x])),sourceMap=new Map(D.resources.map(x=>[x.id,x]));
  let state;
  try{state=L.sanitizeState(JSON.parse(localStorage.getItem('ros2-atlas-v1')||'null'),ids);}catch{state=L.sanitizeState(null,ids);}
  let codeStore=[],route=L.parseRoute(location.hash),activePath='foundation',comparisonView='all',toastTimer,storageWarning=false;
  function save(){try{localStorage.setItem('ros2-atlas-v1',JSON.stringify(state));}catch{if(!storageWarning){storageWarning=true;toast('浏览器存储不可用，进度暂保留在本次页面中。');}}}
  document.body.dataset.theme=state.theme;
  function toast(message){$('toast').textContent=message;$('toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').classList.remove('show'),3200);}
  const urlSafe=url=>/^https?:\/\//.test(url)?url:'#/about';
  const ext=(url,label,cls='')=>`<a class="${cls}" href="${esc(urlSafe(url))}" target="_blank" rel="noopener noreferrer">${label}</a>`;
  const list=items=>`<ul>${(items||[]).map(x=>`<li>${inline(typeof x==='string'?x:JSON.stringify(x))}</li>`).join('')}</ul>`;
  function codeBlock(code,lang='bash',label='',kind='snippet'){
    const index=codeStore.push(String(code))-1;
    const kindName={commands:'终端命令',snippet:'局部片段',complete:'完整文件',concept:'概念示意'}[kind]||'局部片段';
    return `<div class="code-block"><div class="code-head"><span>${esc(label||lang)} · ${kindName}</span><button data-copy="${index}" aria-label="复制${esc(label||lang)}代码">复制</button></div><pre><code>${esc(code)}</code></pre></div>`;
  }
  function refs(sourceIds){return `<ul class="reference-list">${(sourceIds||[]).map(id=>{const r=sourceMap.get(id);if(!r)return '';return `<li>${ext(r.url,`<span>${esc(r.title)}<small>${esc(r.version)} · ${esc(r.verification)}</small></span>${I('external')}`)}${r.sourceUrl?ext(r.sourceUrl,'查看对应源码 ↗','source-code-link'):''}</li>`;}).join('')}</ul>`;}
  function heading(kicker,title,description,meta=''){return `<div class="page-heading"><div class="eyebrow">${esc(kicker)}</div><h1>${esc(title)}</h1><p>${inline(description)}</p>${meta}</div>`;}
  function progress(){ $('progress-count').textContent=`${state.done.length} / ${D.lessons.length}`;$('progress').max=D.lessons.length;$('progress').value=state.done.length;}
  const navItems=[['home','home','学习总览',''],['courses','book','系统教材',D.lessons.length],['compare','code','写法对照',D.comparisons.length],['examples','code','完整示例工程',''],['ecosystem','layers','生态地图',''],['resources','grid','参考出处',D.resources.length],['projects','compass','实战项目',D.projects.length],['troubleshoot','tool','排错与术语','']];
  function nav(){
    const opened=new Set([...document.querySelectorAll('.stage-nav[open]')].map(x=>x.dataset.stage));
    const current=lessonMap.get(route.id);
    $('navigation').innerHTML=navItems.map(([id,icon,label,n])=>`<a class="nav-link ${route.view===id||(id==='courses'&&route.view==='lesson')?'active':''}" href="#/${id}">${I(icon)}${label}${n?`<span class="nav-count">${n}</span>`:''}</a>`).join('')+`<div class="nav-caption">学习章节 / CHAPTERS</div>`+D.stages.map((s,i)=>`<details class="stage-nav" data-stage="${s.id}" ${current?.stage===s.id||opened.has(s.id)?'open':''}><summary><span class="stage-number">0${i+1}</span>${esc(s.title)}</summary>${D.lessons.filter(x=>x.stage===s.id).map(x=>`<a class="lesson-nav ${route.id===x.id?'active':''} ${state.done.includes(x.id)?'done':''}" href="#/lesson/${x.id}">${esc(x.title.split('：')[0])}</a>`).join('')}</details>`).join('')+`<div class="nav-caption">延伸阅读 / LAB</div><a class="nav-link" href="control-lab/index.html">${I('cpu')}ros2_control 学习工坊${I('external')}</a><a class="nav-link" href="#/about">${I('info')}来源与版本说明</a>`;
    progress();
  }
  function heroArt(){return `<div class="hero-art"><svg viewBox="0 0 460 330" role="img" aria-label="从感知、规划、通信到机器人执行的系统图"><defs><pattern id="dots" width="18" height="18" patternUnits="userSpaceOnUse"><circle cx="1" cy="1" r="1" fill="currentColor" opacity=".12"/></pattern><marker id="arrowhead" markerWidth="6" markerHeight="6" refX="5" refY="3" orient="auto"><path d="M0 0L6 3L0 6" fill="#8b9d8b"/></marker></defs><rect x="15" y="10" width="435" height="305" rx="22" fill="url(#dots)"/><ellipse cx="252" cy="287" rx="140" ry="21" fill="var(--soft)" opacity=".5"/><g fill="none" stroke="#8b9d8b" stroke-width="1.3" stroke-dasharray="4 4"><path d="M111 91V144H220" marker-end="url(#arrowhead)"/><path d="M337 94V144H279" marker-end="url(#arrowhead)"/><path d="M250 180V215" marker-end="url(#arrowhead)"/><path d="M105 235H188" marker-end="url(#arrowhead)"/><path d="M313 235H365V139" marker-end="url(#arrowhead)"/></g><g transform="translate(40,35)"><rect width="143" height="59" rx="9" class="art-paper" stroke="var(--line)"/><circle cx="22" cy="29" r="10" fill="var(--soft)"/><path d="M16 29h12M22 23v12" stroke="var(--green)"/><text x="43" y="25" font-size="12" class="art-ink">感知世界</text><text x="43" y="43" font-size="9" class="art-muted">Sensors · Perception</text></g><g transform="translate(266,35)"><rect width="151" height="59" rx="9" class="art-paper" stroke="var(--line)"/><circle cx="23" cy="29" r="10" fill="var(--orange-soft)"/><path d="M18 33l5-10 5 10-5-3z" fill="var(--orange)"/><text x="44" y="25" font-size="12" class="art-ink">理解与规划</text><text x="44" y="43" font-size="9" class="art-muted">Nav2 · MoveIt 2</text></g><g transform="translate(173,116)"><rect width="155" height="65" rx="9" fill="var(--green)"/><g fill="var(--panel)"><circle cx="20" cy="25" r="2"/><circle cx="28" cy="25" r="2"/><circle cx="36" cy="25" r="2"/><circle cx="20" cy="33" r="2"/><circle cx="28" cy="33" r="2"/><circle cx="36" cy="33" r="2"/><circle cx="20" cy="41" r="2"/><circle cx="28" cy="41" r="2"/><circle cx="36" cy="41" r="2"/><text x="54" y="28" font-size="15" font-weight="600">ROS 2</text><text x="54" y="45" font-size="8">NODES · TOPICS · DDS</text></g></g><g transform="translate(33,210)"><rect width="113" height="51" rx="8" class="art-paper" stroke="var(--line)"/><text x="17" y="23" font-size="11" class="art-ink">仿真与验证</text><text x="17" y="39" font-size="8" class="art-muted">Gazebo · rosbag</text></g><g transform="translate(194,208)"><path d="M11 22l50-18 50 18v35L61 76 11 57z" fill="var(--soft)" stroke="var(--green)" stroke-width="1.5"/><path d="M11 22l50 19 50-19M61 41v35" fill="none" stroke="var(--green)" stroke-width="1.2"/><ellipse cx="15" cy="53" rx="9" ry="15" fill="var(--ink)"/><ellipse cx="104" cy="53" rx="9" ry="15" fill="var(--ink)"/><ellipse cx="61" cy="13" rx="17" ry="7" fill="var(--panel)" stroke="var(--green)"/><path d="M44 13V6c0-9 34-9 34 0v7" fill="var(--panel)" stroke="var(--green)"/><ellipse cx="61" cy="5" rx="17" ry="7" fill="var(--soft)" stroke="var(--green)"/><circle cx="61" cy="49" r="3" fill="var(--orange)"/></g><text x="336" y="284" font-size="9" class="art-muted">控制与执行</text><text x="336" y="298" font-size="8" class="art-muted">ros2_control</text></svg><div class="art-caption">ONE GRAPH. A WHOLE ROBOT.</div></div>`;}
  function routeCards(){const p=D.paths.find(x=>x.id===activePath)||D.paths[0];return `<p class="route-description">${esc(p.description)}</p><div class="route-steps">${p.lessons.slice(0,4).map((id,i)=>{const l=lessonMap.get(id);return l?`<a class="route-step" href="#/lesson/${id}"><span class="step-no">STEP 0${i+1}</span><span class="step-arrow">↗</span><h3>${esc(l.shortTitle||l.title.split('：')[0])}</h3><p>${esc(p.captions?.[i]||l.goals[0])}</p></a>`:'';}).join('')}</div>`;}
  function home(){return `<section class="hero"><div class="hero-copy"><div class="eyebrow">A FIELD GUIDE TO ROS 2</div><div class="hero-labels"><span class="tag">中文学习手册</span><span class="tag">Jazzy · Ubuntu 24.04</span><span class="tag">官方资料交叉核对</span></div><h1>从第一个节点，<br>到<em>完整机器人系统。</em></h1><p>把原理、完整代码与实践写进同一套教材。<br>从头到尾离线阅读，读懂每一种写法背后的选择。</p><div class="buttons"><a class="button primary" href="#/lesson/${state.last||'architecture'}">${state.last?'继续学习':'从这里开始'} ${I('arrow')}</a><a class="button" href="#/compare">${I('code')} 对照不同写法</a></div></div>${heroArt()}</section><div class="stats"><div class="stat"><strong>${D.lessons.length}</strong><span>系统学习单元</span></div><div class="stat"><strong>${D.comparisons.length}</strong><span>不同写法对照</span></div><div class="stat"><strong>${D.meta.exerciseCount||40}</strong><span>练习与参考答案</span></div><div class="stat"><strong>${D.meta.codeBlockCount||0}</strong><span>代码与配置示例</span></div></div>${bookBanner()}<section><div class="section-head"><div><span class="section-kicker">YOUR NEXT STEP</span><h2>找到你的学习路线</h2></div><a href="#/courses">查看完整课程 ↗</a></div><div class="route-tabs" role="tablist" aria-label="学习方向">${D.paths.map(p=>`<button class="route-tab" role="tab" aria-controls="route-result" aria-selected="${activePath===p.id}" data-path="${p.id}">${esc(p.title)}</button>`).join('')}</div><div id="route-result" role="tabpanel">${routeCards()}</div></section><section class="section"><div class="section-head"><div><span class="section-kicker">CONNECT THE DOTS</span><h2>理解原理，也读懂工程</h2></div></div><div class="featured-grid"><a class="feature-block" href="#/compare/compare-publisher"><div class="feature-top"><span class="tag">C++ ↔ Python</span><h3>同一个任务，不止一种写法</h3><p>从 API 到工程结构，对齐相同的行为与各自的边界。</p></div><pre class="mini-code"><span class="dim">// rclcpp</span>   create_publisher&lt;String&gt;("status", 10)
<span class="dim">#  rclpy</span>    create_publisher(String, "status", 10)</pre><div class="feature-bottom"><span>话题 · 服务 · 动作 · 参数 · Launch</span><span>查看 ${D.comparisons.length} 组对照 ↗</span></div></a><a class="feature-block feature-green" href="#/ecosystem"><div class="feature-top"><span class="tag">THE ECOSYSTEM</span><h3>把工具放回它的位置</h3><p>从传感器到执行器，看见整个机器人软件栈。</p><div class="mini-flow"><span>感知</span>→<span>规划</span>→<span>控制</span></div></div><div class="feature-bottom"><span>Nav2 / MoveIt / Gazebo / micro-ROS</span><span>展开生态地图 ↗</span></div></a></div></section><section class="section"><div class="section-head"><div><span class="section-kicker">BUILT ON PRIMARY SOURCES</span><h2>每个知识点，都有来处</h2></div><a href="#/resources">打开全部资料 ↗</a></div><div class="source-strip">${[['https://docs.ros.org/en/jazzy/','ROS 2 Docs'],['https://github.com/ros2/examples/tree/jazzy','ros2/examples'],['https://control.ros.org/jazzy/','ros2_control'],['https://docs.nav2.org/jazzy/','Nav2'],['https://moveit.picknik.ai/','MoveIt 2'],['https://gazebosim.org/docs/harmonic/','Gazebo'],['https://zsc.github.io/ros2_tutorial/','zsc 中文教程'],['https://rzl6.github.io/ROS2_Tuition/','ROS2 理论与实践']].map(([u,t])=>ext(u,esc(t)+' ↗')).join('')}</div><div class="notice">全部课程与代码可离线阅读，原始来源仅作核对与延伸。主线固定为 <strong>Jazzy</strong>；遇到 Humble、Rolling 或厂商独立版本时，先看章节里的版本说明，再复用代码。<a href="#/about">查看资料核查记录 →</a></div></section>`;}
  function lessonRow(l,i){return `<a class="lesson-row" href="#/lesson/${l.id}"><span>${String(i+1).padStart(2,'0')}</span><div><h3>${esc(l.title)}</h3><p>${esc(l.summary.slice(0,100))}</p></div><div class="row-end"><span>${esc(l.level||'系统学习')}</span><span class="${state.done.includes(l.id)?'completed':''}">${state.done.includes(l.id)?'✓':'↗'}</span></div></a>`;}
  function courses(){return heading('THE COMPLETE TEXTBOOK','一条主线，读懂整个系统','从基础概念出发，逐步连接通信、工程化、机器人模型、控制与高阶生态。正文、代码、完整案例与习题答案均在本站，可离线阅读。')+bookBanner()+D.stages.map((s,i)=>`<section class="stage-section"><div class="stage-heading"><span class="stage-badge">0${i+1}</span><div><h2>${esc(s.title)}</h2><p>${esc(s.description)}</p></div></div><div class="lesson-list">${D.lessons.filter(x=>x.stage===s.id).map(l=>lessonRow(l,D.lessons.indexOf(l))).join('')}</div></section>`).join('');}
  function qosWidget(){return `<div class="qos-widget"><h3>试一试：这两个端点能匹配吗？</h3><p class="code-note" style="margin:8px 0">本实验只检查 Reliability 与 Durability；实际通信还受类型、名称、其他 QoS 和网络影响。</p><div class="qos-fields">${['offered','requested'].map((role,i)=>`<div><h3>${i?'订阅者要求':'发布者提供'}</h3><label>可靠性<select data-qos="${role}-reliability"><option value="reliable">Reliable · 可靠</option><option value="best_effort">Best effort · 尽力</option></select></label><label>持久性<select data-qos="${role}-durability"><option value="volatile">Volatile · 不保留历史</option><option value="transient_local">Transient local · 保留历史</option></select></label></div>`).join('')}</div><div id="qos-result" class="qos-result" role="status">这两项 QoS 可以匹配。继续检查类型、名称与网络。</div></div>`;}
  function lesson(id){const l=lessonMap.get(id);if(!l)return heading('PAGE NOT FOUND','没有找到这个章节','可以从系统课程重新选择。')+'<a class="button" href="#/courses">返回课程</a>';
    state.last=id;save();const idx=D.lessons.indexOf(l),stage=D.stages.find(s=>s.id===l.stage),prior=D.lessons[idx-1],next=D.lessons[idx+1];
    const exercise=typeof l.exercise==='string'?l.exercise:l.exercise?.question||'',answer=l.exerciseAnswer||l.exercise?.answer||'';
    const related=D.comparisons.filter(c=>(c.relatedLessons||[]).includes(id));
    return `<div class="reader-grid"><article class="article">${heading(`${stage?.title||'系统课程'} / ${String(idx+1).padStart(2,'0')}`,l.title,l.summary,`<div class="meta"><span class="tag">${esc(l.version||'Jazzy')}</span><span>练习约 ${l.minutes||20} 分钟</span><span>${l.sourceIds.length} 个依据来源</span></div>`)}<div class="lesson-actions"><button class="button small ${state.done.includes(id)?'is-done':''}" data-action="done">${I('check')}${state.done.includes(id)?'已完成 · 取消标记':'标记为已完成'}</button><button class="button small bookmark-button ${state.stars.includes(id)?'selected':''}" data-action="star">${I('bookmark')}${state.stars.includes(id)?'已收藏':'收藏本章'}</button><button class="button small" data-action="export-lesson">${I('download')}导出本章</button><button class="button small" data-action="print">打印</button></div><h2 id="goals">这一章，你会学到</h2><div class="goal-list">${list(l.goals)}</div>${l.prerequisites?`<div class="notice"><strong>开始之前</strong><br>${inline(Array.isArray(l.prerequisites)?l.prerequisites.join('；'):l.prerequisites)}</div>`:''}<h2 id="concepts">先建立正确的理解</h2>${l.concepts.map((p,i)=>`<p>${inline(p)}</p>`).join('')}${id==='architecture'?'<div class="inline-diagram"><span>应用节点</span><em>↓</em><span>rclcpp / rclpy</span><em>↓</em><span>RMW</span><em>↓</em><span>通信中间件</span></div>':''}${id==='qos'?qosWidget():''}${window.Textbook.renderExpanded(l,codeBlock)}<h2 id="practice">基础验证流程</h2>${l.steps.map((step,i)=>{const s=typeof step==='string'?{title:`步骤 ${i+1}`,body:step}:step;return `<section class="step" data-step="${i+1}"><h3>${esc(s.title||`步骤 ${i+1}`)}</h3><p>${inline(s.body||s.description||'')}</p>${s.code?codeBlock(s.code,s.language||'bash',s.label||s.title,s.type||'commands'):''}</section>`;}).join('')}${(l.commands||[]).map(c=>codeBlock(c.code,c.language||'bash',c.label||'练习命令',c.type||'commands')).join('')}<div class="notice"><strong>你应该看到</strong>${list(l.expected)}</div>${related.length?`<h3>把这章放到不同写法里看</h3><div class="source-strip">${related.map(c=>`<a href="#/compare/${c.id}">${esc(c.title)} ↗</a>`).join('')}</div>`:''}<h2 id="pitfalls">常见问题与边界</h2>${list(l.pitfalls)}<section class="exercise" id="exercise"><span>CHECK YOUR UNDERSTANDING</span><h3>用一个练习检查理解</h3><p>${inline(exercise)}</p><details class="answer"><summary>展开参考答案</summary><p>${inline(answer)}</p></details></section><h2 id="references">参考出处</h2><details class="source-appendix"><summary>展开本章依据与延伸阅读（外部网页）</summary>${refs(l.sourceIds)}</details><p class="code-note">${esc(l.validation||'按版本资料核对。代码需要在读者自己的匹配环境中验证。')}</p><div class="next-prev"><div>${prior?`<a href="#/lesson/${prior.id}"><small>← 上一章</small><strong>${esc(prior.title)}</strong></a>`:''}</div><div>${next?`<a href="#/lesson/${next.id}"><small>下一章 →</small><strong>${esc(next.title)}</strong></a>`:'<a href="#/projects">去完成一个实战项目 →</a>'}</div></div></article><aside class="toc" aria-label="本页目录"><strong>本页内容</strong>${(l.sections||[]).map((s,i)=>`<button class="deep-link" data-scroll="deep-${i}">${i+1}. ${esc(s.title)}</button>`).join('')}${[['goals','学习目标'],['concepts','概念与原理'],['practice','动手验证'],['pitfalls','排错与边界'],['exercise','练习与答案'],['references','官方依据']].map(([id,label])=>`<button data-scroll="${id}">${label}</button>`).join('')}<div class="toc-footer">主线 / ROS 2 Jazzy<br>核对 / 2026.11.06<br><a href="#/compare">查看不同写法 ↗</a><br><a href="downloads/atlas_examples.zip" download>下载完整示例 ↗</a></div></aside></div>`;
  }
  function comparisons(id){const c=D.comparisons.find(x=>x.id===id);if(!c)return heading('SAME TASK, DIFFERENT EXPRESSIONS','读懂不同写法的对应关系','先对齐任务和可观察行为，再比较 API、工程结构和适用场景。标注为“局部片段”的代码需要放入完整工程；完整通信示例可直接下载。',`<div class="buttons"><a class="button" href="downloads/atlas_examples.zip" download>${I('download')}下载 C++ / Python 完整示例</a></div>`)+`<div class="comparison-list">${D.comparisons.map((c,i)=>`<a href="#/compare/${c.id}" class="comparison-card"><span>COMPARISON ${String(i+1).padStart(2,'0')}</span><h2>${esc(c.title)}</h2><p>${esc(c.question)}</p><div class="variant-tags">${c.variants.map(v=>`<span class="tag">${esc(v.label)}</span>`).join('')}</div></a>`).join('')}</div>`;
    return heading('WRITING COMPARISON',c.title,c.question,`<div class="meta"><span class="tag">${esc(c.version||'Jazzy')}</span><a href="#/compare">← 全部对照</a></div>`)+`<div class="compare-controls" role="group" aria-label="选择对照写法"><button data-variant="all" aria-pressed="${comparisonView==='all'}">并排对照</button>${c.variants.map((v,i)=>`<button data-variant="${i}" aria-pressed="${comparisonView===String(i)}">${esc(v.label)}</button>`).join('')}</div><div class="compare-columns ${comparisonView!=='all'?'single':''}">${c.variants.map((v,i)=>comparisonView==='all'||comparisonView===String(i)?`<section class="variant"><h2>${esc(v.label)}</h2><p>${inline(v.when||'')}</p>${codeBlock(v.code,v.language,v.label,v.type||'snippet')}<p class="code-note">${inline(v.scope||'')}</p></section>`:'').join('')}</div><section class="compare-notes"><h2>相同目标，各自的边界</h2>${list(c.notes)}</section>${c.id==='compare-qos'?qosWidget():''}<div class="notice warm">${inline(c.validation||'以下说明依据对应版本文档，片段本身不代表完整工程。')} 完整工程见 <a href="downloads/atlas_examples.zip" download>示例下载</a>。</div><h2 style="font-size:20px;margin-top:28px">依据来源</h2>${refs(c.sourceIds)}`;
  }
  function bookBanner(){return `<section class="book-banner"><div><span class="section-kicker">THE OFFLINE READING EDITION</span><h2>把整个知识体系，读成一本书</h2><p>${D.lessons.length} 章正文、代码、案例与答案。单文件连续阅读，不依赖 JavaScript 或网络。</p></div><div class="buttons"><a class="button primary" href="book.html">打开完整教材 ${I('arrow')}</a><a class="button" href="downloads/ros2-learning-guide.md" download>下载 Markdown</a></div></section>`;}
  function examples(){return heading('COMPLETE SOURCE FILES','完整工程，逐个文件读','这里直接展示随教材提供的工程文件。先按 README 建立工作空间，再对照源码。下载包包含源码和构建说明，章节代码包另收录正文中标注为“完整文件”的例子。')+`<div class="notice">${inline(D.meta.exampleValidation)}</div><div class="buttons"><a class="button primary" href="downloads/atlas_examples.zip" download>${I('download')}下载已验证的通信工程</a><a class="button" href="downloads/chapter-code.zip" download>下载各章完整代码文件</a><a class="button" href="book.html#examples">在完整教材中连续阅读</a></div><div class="notice warm">“完整文件”与“完整项目”不同。章节代码包保留文件内容及对应章节清单；依赖、安装路径、组合顺序和验证方法请同时阅读该章正文。</div>${(D.exampleFiles||[]).map((f,i)=>`<details class="project-file" ${f.path==='README.md'?'open':''}><summary>${esc(f.path)}</summary>${codeBlock(f.code,f.language,f.path,'complete')}</details>`).join('')}`;}
  function resourceRows(rows){return rows.length?rows.map((r,i)=>`<article class="resource"><span class="resource-index">${String(i+1).padStart(2,'0')}</span><div><h3>${ext(r.url,esc(r.title)+' ↗')}</h3><p>${esc(r.description)}</p><span class="resource-domain">${esc(new URL(r.url).hostname)}</span>${r.sourceUrl?` · ${ext(r.sourceUrl,'官方／作者源码 ↗','resource-domain')}`:''}${r.versionNote?`<p><strong>版本提示：</strong>${esc(r.versionNote)}</p>`:''}</div><div class="resource-meta"><span class="tag">${esc(r.version)}</span><span class="tag">${esc(r.category)}</span><small>${esc(r.verification)}</small></div></article>`).join(''):'<div class="empty">没有匹配的资料。试试更短的关键词或清除筛选。</div>';}
  function catalogRows(site,query=''){const rows=D.catalog.filter(r=>r.site===site&&(`${r.title} ${r.url}`).toLowerCase().includes(query.toLowerCase().trim()));return rows.length?rows.map(r=>`<div class="catalog-item"><div><strong>${esc(r.title)}</strong><div class="source-strip">${(r.lessons||[]).map(id=>`<a href="#/lesson/${id}">离线阅读 · ${esc(lessonMap.get(id).title.split('：')[0])}</a>`).join('')}</div></div><a href="${esc(r.url)}" target="_blank" rel="noopener noreferrer">原出处 ↗</a></div>`).join(''):'<div class="empty">该教程中没有匹配页面。</div>';}
  function resources(){return heading('SOURCE LIBRARY','有出处的知识，才经得起实践',`这里列出本次纳入的全部 ${D.resources.length} 个来源入口，以及两套已下载教程的 ${D.catalog.length} 个页面。官方资料优先，教程用于补充学习视角；每条资料保留版本与核查方式。`)+`<div class="buttons" style="margin:0 0 25px"><a class="button small" href="downloads/sources.json" download>${I('download')}下载全部来源 JSON</a><a class="button small" href="downloads/bibliography.md" download>导出完整资料清单</a></div><div class="filters"><input id="resource-query" type="search" aria-label="筛选资料关键词" placeholder="搜索文档、项目或关键词…"><label>分类<select id="resource-category"><option value="">全部分类</option>${[...new Set(D.resources.map(x=>x.category))].sort().map(c=>`<option>${esc(c)}</option>`).join('')}</select></label><label>版本<select id="resource-version"><option value="">全部版本</option><option>Jazzy</option><option>Humble</option><option>Rolling</option></select></label><button class="button small" data-action="clear-filters">清除筛选</button></div><div id="resource-count" class="filter-count" role="status">${D.resources.length} / ${D.resources.length} 个来源</div><div id="resource-list" class="resource-list">${resourceRows(D.resources)}</div><section class="section"><div class="section-head"><div><span class="section-kicker">EVERY AVAILABLE PAGE</span><h2>两套教程的全部页面</h2></div></div><p class="code-note" style="margin:0 0 20px">以下标题与路径逐项来自已克隆文件，页面未逐一联网复测。每项提供对应的本站离线章节；原出处仅用于追溯。对应关系按主题整合，不代表逐页翻译。</p>${[['zsc','zsc · ROS2 完全教程','当前仓库只有第 1–22 章；目录提到的第 23、24 章尚无对应文件。'],['rzl6','ROS2 理论与实践 · 核心篇','Humble / Ubuntu 22.04，包含 C++、Python、launch、TF 与模型的细分页面。']].map(([site,title,note])=>`<details class="catalog-details"><summary>${title} <span class="tag">${D.catalog.filter(r=>r.site===site).length} 页</span></summary><div class="catalog-inner"><p class="code-note" style="margin:0 0 15px">${note}</p><input class="catalog-filter" data-catalog="${site}" type="search" aria-label="筛选${title}" placeholder="在这套教程中查找…"><div id="catalog-${site}">${catalogRows(site)}</div></div></details>`).join('')}</section>`;}
  function filterResources(){const q=$('resource-query').value.toLowerCase().trim(),c=$('resource-category').value,v=$('resource-version').value;const rows=D.resources.filter(r=>(!c||r.category===c)&&(!v||r.version.toLowerCase().includes(v.toLowerCase()))&&(!q||`${r.title} ${r.description} ${r.url} ${r.version}`.toLowerCase().includes(q)));$('resource-list').innerHTML=resourceRows(rows);$('resource-count').textContent=`${rows.length} / ${D.resources.length} 个来源`;}
  function ecosystem(){return heading('THE ROBOTICS ECOSYSTEM','把每个工具，放回系统的位置','ROS 2 提供连接组件的基础。导航、控制、感知、仿真和部署各有自己的职责与依赖；从下面任一层进入，再回到整条数据链。')+`<div class="inline-diagram"><span>传感器与感知</span><em>→</em><span>定位与规划</span><em>→</em><span>控制与硬件</span><em>↺</em><span>反馈与观测</span></div><div class="ecosystem-grid">${D.ecosystems.map(g=>`<section class="eco-card"><span class="eco-icon">${I(g.icon||'layers')}</span><h2>${esc(g.title)}</h2><p>${esc(g.description)}</p>${g.lessons.filter(id=>lessonMap.has(id)).map(id=>`<a href="#/lesson/${id}">${esc(lessonMap.get(id).shortTitle||lessonMap.get(id).title.split('：')[0])}<span>↗</span></a>`).join('')}</section>`).join('')}</div><div class="notice warm">工具“支持 ROS 2”不代表任意版本都能混用。尤其注意 Jazzy / Gazebo Harmonic、厂商 SDK 与 GPU 驱动的兼容关系。<a href="#/about">查看已发现的版本差异 →</a></div>`;}
  function projects(){return heading('BUILD SOMETHING THAT WORKS','用五个项目，把知识串起来','每个项目以可观察的阶段结果收尾。先在独立工作空间和仿真中完成验证，再根据设备接口接入真实硬件。')+D.projects.map((p,i)=>`<section class="project"><span class="project-no">0${i+1}</span><div><div class="eyebrow">${esc(p.level)}</div><h2>${esc(p.title)}</h2><p>${esc(p.summary)}</p><div class="source-strip">${p.lessons.filter(id=>lessonMap.has(id)).map(id=>`<a href="#/lesson/${id}">${esc(lessonMap.get(id).shortTitle||lessonMap.get(id).title.split('：')[0])}</a>`).join('')}</div><h3>里程碑与验收</h3><ol class="milestones">${p.milestones.map(x=>`<li>${inline(x)}</li>`).join('')}</ol>${codeBlock(p.code,'bash','起点与检查命令','commands')}<div class="notice">${inline(p.note)}</div>${p.id==='first-nodes'?'<a class="button primary" href="downloads/atlas_examples.zip" download>下载完整练习工程 ↓</a>':''}${p.id==='diffbot'?'<a class="button" href="control-lab/index.html">打开 ros2_control 交互工坊 ↗</a>':''}${refs(p.sourceIds)}</div></section>`).join('');}
  function troubleshoot(){return heading('WHEN THINGS GO WRONG','从症状出发，找到下一条证据','先观察系统实际运行的状态，再调整代码与配置。下面的检查按依赖顺序排列，避免一次改动多个变量。')+D.issues.map(x=>`<details class="issue"><summary>${esc(x.title)}</summary><p>${inline(x.explanation)}</p>${list(x.checks)}${codeBlock(x.code,'bash','检查命令','commands')}<p><strong>判断依据：</strong>${inline(x.expected)}</p><a class="button small" href="#/lesson/${x.lesson}">回到相关章节 →</a><br><br></details>`).join('')+`<section class="section"><div class="section-head"><h2>常用术语，放在一起理解</h2></div><div class="glossary">${D.glossary.map(t=>`<article class="term"><h3>${esc(t.title)}</h3><small>${esc(t.en)}</small><p>${esc(t.description)}</p></article>`).join('')}</div></section>`;}
  function saved(){const stars=D.lessons.filter(l=>state.stars.includes(l.id));return heading('YOUR READING DESK','我的学习记录','进度和收藏只保存在当前浏览器。换设备、浏览器或打开地址后，记录不会自动同步。')+`<div class="notice">已完成 ${state.done.length} / ${D.lessons.length} 章，收藏 ${state.stars.length} 章。${state.last?`<a href="#/lesson/${state.last}">继续上次阅读 →</a>`:''}</div><div class="section-head"><h2>收藏的章节</h2></div>${stars.length?`<div class="lesson-list">${stars.map(l=>lessonRow(l,D.lessons.indexOf(l))).join('')}</div>`:'<div class="empty">在章节上方点击“收藏本章”，就可以从这里快速回到它。</div>'}<div class="buttons"><a class="button" href="downloads/ros2-learning-guide.md" download>${I('download')}下载完整学习文档</a><button class="button" data-action="export-progress">导出进度备份</button><label class="button">导入进度备份<input id="import-progress" type="file" accept="application/json,.json" hidden></label></div>`;}
  function about(){return heading('PROVENANCE & EDITORIAL NOTES','先认清版本，再相信代码','这是基于官方和维护者资料整理的独立中文学习手册。每章提供原始依据，资料库保留本次纳入的全部来源。')+`<div class="about-prose"><h2>内容与版本</h2><p>主线是 Ubuntu 24.04、ROS 2 Jazzy 和 Gazebo Harmonic。Jazzy 不是当前最新发行版；选择它是为了与当前参考工程一致。核查日期为 2026-11-06。</p><p>本站包含 ${D.lessons.length} 章原创讲解、${D.comparisons.length} 组不同写法对照、${D.resources.length} 个来源入口和 ${D.catalog.length} 个本地教程页面索引。资料目录覆盖本次选定的主要生态，并非互联网上全部 ROS 2 资源。</p><h2>怎样理解“已核对”</h2><p>官方 ROS 文档站部分页面触发访问验证，已通过 ros2/ros2_documentation 的 Jazzy 分支及官方示例源码交叉阅读。页面可访问、API 核对、实际编译、仿真运行与实机验证是不同层次；资料卡和章节保留各自的核查范围。</p><div class="notice">${inline(D.meta.exampleValidation||'完整教学工程的验证状态见下载包 README 与项目验证记录。其余示例按文档核查，不代表逐项实机验证。')}</div><h2>本次核查发现的差异</h2>${D.versionNotes.map(n=>`<h3>${esc(n.topic)}</h3><p>${esc(n.detail)}</p>`).join('')}<h2>内容来源与使用</h2><p>正文为原创中文综合说明。两套下载教程以目录和原网页链接收录；zsc 仓库未提供明确许可证，本站不再分发其正文。原作者代码和文档的许可仍由各自项目规定。</p><p>本站整合工作区已有的 ros2_control 工坊，并保留其第三方说明与 Apache-2.0 许可。<a href="control-lab/THIRD_PARTY_NOTICES.md">查看控制工坊出处说明 ↗</a></p><h2>离线与可重复学习</h2><p>课程、交互、图解和全文搜索不依赖 CDN 或远程服务。来源网页需要联网。学习记录保存在当前浏览器，支持导入导出；代码复制受浏览器权限限制时，会出现手动复制面板。</p><div class="buttons"><a class="button" href="downloads/ros2-learning-guide.md" download>下载学习文档</a><a class="button" href="downloads/bibliography.md" download>下载全部资料清单</a><a class="button" href="downloads/atlas_examples.zip" download>下载教学工程</a><a class="button" href="THIRD_PARTY_NOTICES.md">来源与许可说明</a></div></div>`;}
  const searchDocs=[...D.lessons.map(x=>({title:x.title,text:JSON.stringify(x),kind:'系统课程',url:`#/lesson/${x.id}`,summary:x.summary})),...D.comparisons.map(x=>({title:x.title,text:JSON.stringify(x),kind:'写法对照',url:`#/compare/${x.id}`,summary:x.question})),...D.resources.map(x=>({title:x.title,text:JSON.stringify(x),kind:`资料 · ${x.version}`,url:x.url,summary:x.description})),...D.catalog.map(x=>({title:x.title,text:x.site+' '+x.title+' '+x.url,kind:`教程对应 · ${x.site}`,url:`#/lesson/${x.lessons[0]}`,summary:'按主题整合的本站离线章节；原出处见参考附录'}))];
  function search(){const q=$('search-input').value,results=L.search(searchDocs,q);if(!q.trim()){$('search-results').innerHTML='<p class="search-hint">输入概念、API 或项目名，搜索课程正文、代码和全部来源。</p><div class="search-chips">'+['QoS','rclcpp','Nav2','TwistStamped','launch','micro-ROS'].map(x=>`<button data-search="${x}">${x}</button>`).join('')+'</div>';return;}$('search-results').innerHTML=`<p class="filter-count">找到 ${results.length} 项${results.length>60?'，显示前 60 项':''}</p>`+(results.length?results.slice(0,60).map(r=>`<a class="search-result" href="${esc(r.url)}" ${r.url.startsWith('http')?'target="_blank" rel="noopener noreferrer"':''}><small>${esc(r.kind)}</small><h3>${esc(r.title)} ${r.url.startsWith('http')?'↗':''}</h3><p>${esc(r.summary.slice(0,130))}</p></a>`).join(''):'<div class="empty">没有找到匹配项。试试“话题”“参数”或英文包名。</div>');}
  function menu(open){document.body.classList.toggle('menu-open',open);$('backdrop').hidden=!open;document.querySelector('[data-action=menu]').setAttribute('aria-expanded',String(open));if(open)$('navigation').querySelector('a')?.focus();}
  function render(preserve=false){const y=window.scrollY;codeStore=[];route=L.parseRoute(location.hash);const l=lessonMap.get(route.id);let html;switch(route.view){case 'courses':html=courses();break;case 'lesson':html=lesson(route.id);break;case 'compare':html=comparisons(route.id);break;case 'examples':html=examples();break;case 'resources':html=resources();break;case 'ecosystem':html=ecosystem();break;case 'projects':html=projects();break;case 'troubleshoot':html=troubleshoot();break;case 'saved':html=saved();break;case 'about':html=about();break;default:html=home();}
    $('main').innerHTML=html;$('breadcrumb').textContent=route.view==='lesson'?(l?.title||'章节'):navItems.find(x=>x[0]===route.view)?.[2]||({saved:'我的记录',about:'来源与版本说明'}[route.view])||'总览';document.title=`${$('breadcrumb').textContent} · ROS 2 学习图谱`;nav();icons();menu(false);if(preserve)window.scrollTo(0,y);else{window.scrollTo(0,0);$('main').focus({preventScroll:true});}}
  function download(name,text,type='text/plain'){const blob=new Blob([text],{type}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);}
  function lessonMarkdown(l){const md=[`# ${l.title}`,l.summary,'## 学习目标',...l.goals.map(x=>'- '+x),'## 概念',...l.concepts,'## 实践'];l.steps.forEach(s=>{if(typeof s==='string')md.push(s);else{md.push('### '+s.title,s.body||'');if(s.code)md.push('```'+(s.language||'bash'),s.code,'```');}});(l.commands||[]).forEach(c=>md.push('### '+c.label,'```'+(c.language||'bash'),c.code,'```'));md.push(window.Textbook.expandedMarkdown(l));md.push('## 预期结果',...l.expected.map(x=>'- '+x),'## 常见问题',...l.pitfalls.map(x=>'- '+x),'## 练习',typeof l.exercise==='string'?l.exercise:l.exercise.question,'### 参考答案',l.exerciseAnswer||l.exercise.answer||'','## 依据',...l.sourceIds.map(id=>{const r=sourceMap.get(id);return r?`- [${r.title}](${r.url}) · ${r.version}`:'';}));return md.join('\n\n');}
  function updateQos(){const read=role=>({reliability:document.querySelector(`[data-qos="${role}-reliability"]`).value,durability:document.querySelector(`[data-qos="${role}-durability"]`).value});const ok=L.qosCompatible(read('offered'),read('requested'));$('qos-result').classList.toggle('bad',!ok);$('qos-result').textContent=ok?'这两项 QoS 可以匹配。继续检查类型、名称与网络。':'这两项 QoS 不兼容：发布者提供的能力没有满足订阅者的要求。';}
  document.addEventListener('click',async event=>{const el=event.target.closest('button,a');if(!el)return;
    if(el.classList.contains('skip')){event.preventDefault();$('main').focus({preventScroll:true});$('main').scrollIntoView();return;}
    if(el.dataset.close){$(el.dataset.close).close();return;}
    if(el.dataset.scroll){$(el.dataset.scroll)?.scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'});return;}
    if(el.dataset.copy!==undefined){const text=codeStore[Number(el.dataset.copy)];if(text===undefined)return;try{await navigator.clipboard.writeText(text);toast('代码已复制');}catch{$('copy-text').value=text;$('copy-dialog').showModal();$('copy-text').select();}return;}
    if(el.dataset.path){activePath=el.dataset.path;document.querySelectorAll('[data-path]').forEach(b=>b.setAttribute('aria-selected',String(b===el)));$('route-result').innerHTML=routeCards();return;}
    if(el.dataset.variant!==undefined){comparisonView=el.dataset.variant;render(true);document.querySelector(`[data-variant="${comparisonView}"]`)?.focus({preventScroll:true});return;}
    if(el.dataset.search){$('search-input').value=el.dataset.search;search();$('search-input').focus();return;}
    if(el.classList.contains('search-result'))$('search-dialog').close();
    switch(el.dataset.action){
      case 'menu':menu(!document.body.classList.contains('menu-open'));break;
      case 'search':$('search-dialog').showModal();search();$('search-input').focus();break;
      case 'theme':state.theme=state.theme==='light'?'dark':'light';document.body.dataset.theme=state.theme;save();break;
      case 'done':{const id=route.id;state.done=state.done.includes(id)?state.done.filter(x=>x!==id):[...state.done,id];save();render(true);document.querySelector('[data-action=done]')?.focus({preventScroll:true});break;}
      case 'star':{const id=route.id;state.stars=state.stars.includes(id)?state.stars.filter(x=>x!==id):[...state.stars,id];save();render(true);document.querySelector('[data-action=star]')?.focus({preventScroll:true});break;}
      case 'export-lesson':{const l=lessonMap.get(route.id);if(l)download(l.id+'.md',lessonMarkdown(l),'text/markdown');break;}
      case 'export-progress':download('ros2-learning-progress.json',JSON.stringify({format:'ros2-atlas-v1',...state},null,2),'application/json');break;
      case 'print':window.print();break;
      case 'clear-filters':$('resource-query').value='';$('resource-category').value='';$('resource-version').value='';filterResources();break;
    }
  });
  document.addEventListener('input',event=>{const el=event.target;if(el.id==='search-input')search();if(el.id==='resource-query')filterResources();if(el.dataset.catalog)$('catalog-'+el.dataset.catalog).innerHTML=catalogRows(el.dataset.catalog,el.value);});
  document.addEventListener('change',async event=>{const el=event.target;if(['resource-category','resource-version'].includes(el.id))filterResources();if(el.dataset.qos)updateQos();if(el.id==='import-progress'&&el.files[0]){try{if(el.files[0].size>100000)throw new Error('size');const raw=JSON.parse(await el.files[0].text());if(raw.format!=='ros2-atlas-v1')throw new Error('format');state=L.sanitizeState(raw,ids);save();document.body.dataset.theme=state.theme;render(true);toast('学习进度已导入');}catch{toast('无法导入：请选择本站导出的有效进度 JSON。');}}});
  document.addEventListener('keydown',event=>{if(event.key==='Escape'){const open=[...document.querySelectorAll('dialog[open]')].at(-1);if(open){event.preventDefault();open.close();return;}}const typing=/INPUT|TEXTAREA|SELECT/.test(document.activeElement?.tagName)||document.activeElement?.isContentEditable;if((event.key==='/'&&!typing)||(event.key.toLowerCase()==='k'&&(event.ctrlKey||event.metaKey))){event.preventDefault();if(!$('search-dialog').open)$('search-dialog').showModal();search();$('search-input').focus();}if(event.key==='Escape'&&document.body.classList.contains('menu-open')){menu(false);document.querySelector('[data-action=menu]').focus();}if(event.key==='Tab'&&document.body.classList.contains('menu-open')&&!document.querySelector('dialog[open]')){const nodes=[...$('sidebar').querySelectorAll('a,button,summary')].filter(x=>x.getClientRects().length),first=nodes[0],last=nodes[nodes.length-1];if(event.shiftKey&&document.activeElement===first){event.preventDefault();last.focus();}else if(!event.shiftKey&&document.activeElement===last){event.preventDefault();first.focus();}}if(event.target.matches('[data-path]')&&['ArrowLeft','ArrowRight','Home','End'].includes(event.key)){event.preventDefault();const tabs=[...document.querySelectorAll('[data-path]')],i=tabs.indexOf(event.target),n=event.key==='Home'?0:event.key==='End'?tabs.length-1:(i+(event.key==='ArrowRight'?1:-1)+tabs.length)%tabs.length;tabs[n].focus();tabs[n].click();}});
  $('backdrop').addEventListener('click',()=>menu(false));
  window.addEventListener('hashchange',()=>{document.querySelectorAll('dialog[open]').forEach(d=>d.close());comparisonView='all';render();});
  render();
})();
